public double GetMean(ItemRoot root, AttributeGrade grade)
	{
		double additionValue = root.GetAdditionValue(AttributeType);
		double num = ((grade != AttributeGrade.Primary) ? 0.5 : 1.0);
		if (Style == AttributeStyle.Penalty)
		{
			num *= -1.0;
		}
		if (PowerLevel == AttributePowerLevel.ExtremeHigh)
		{
			num *= 1.0;
		}
		if (PowerLevel == AttributePowerLevel.High)
		{
			num *= 0.8;
		}
		if (PowerLevel == AttributePowerLevel.Medium)
		{
			num *= 0.6;
		}
		if (PowerLevel == AttributePowerLevel.Low)
		{
			num *= 0.4;
		}
		if (PowerLevel == AttributePowerLevel.ExtremeLow)
		{
			num *= 0.2;
		}
		return additionValue * num;
	}

