public static bool IsCombineable(this List<Item> items)
	{
		if (items.Count == 3)
		{
			ResourceCategory category = items[0].Type.GetResourceCategory();
			ResourceType type = items[0].Type;
			QualityGrade qualityGrade = (from i in items
				select i.ItemGrade into i
				orderby i
				select i).First();
			int num = (int)(qualityGrade + 1);
			int level = items[0].Level;
			if (items.All((Item i) => i.Type.GetResourceCategory() == category && i.Type == type) && items.Any((Item i) => i.ItemGrade != QualityGrade.Ancient) && items.All((Item i) => i.Level == level) && (num < 5 || (num == 5 && GetForgeLevel() >= 2)) && (category.IsWeapon() || category.IsArmor() || category == ResourceCategory.Consumable || (category == ResourceCategory.Gem && level < ItemExtensions.MaxGemLevel)))
			{
				return GameWorld.instance.PlayerProfile.Buildings.Any((KeyValuePair<TownSlot, IBuildingProfile> b) => b.Value != null && b.Value.BuildingType == BuildingType.ForgingFacility) && ((ForgingFacility)GameWorld.instance.PlayerProfile.Buildings.Values.First((IBuildingProfile v) => v != null && v.BuildingType == BuildingType.ForgingFacility)).Level >= 1;
			}
		}
		return false;
	}

private static int GetForgeLevel()
	{
		if (GameWorld.instance.PlayerProfile.Buildings.Select((KeyValuePair<TownSlot, IBuildingProfile> s) => s.Value).FirstOrDefault((IBuildingProfile b) => b != null && b.BuildingType == BuildingType.ForgingFacility) is ForgingFacility forgingFacility)
		{
			return forgingFacility.Level;
		}
		return 1;
	}

public static double GetCombineCost(List<Item> items)
	{
		if (items.Any((Item i) => i.Type.GetResourceCategory() == ResourceCategory.Gem))
		{
			if (items.Any())
			{
				Item item = items.OrderBy((Item i) => i.Level).First();
				int level = item.Level;
				if (level > 9)
				{
					return 20000.0;
				}
			}
			return 0.0;
		}
		if (items.Any())
		{
			Item item2 = items.OrderBy((Item i) => i.Level).First();
			int level2 = item2.Level;
			if (level2 > 7)
			{
				return 50000.0;
			}
		}
		return 0.0;
	}

public static List<ResourceUpdate> CombineItems(this List<Item> items)
	{
		CombineResult combineResult = CalculateCombineResult(items);
		if (combineResult.Produced.Count > 0)
		{
			GameWorld.instance.PlayerProfile.SpendMoney(GetCombineCost(items));
			GameWorld.instance.PlayerProfile.BatchResourceUpdate(combineResult.Consumed);
			GameWorld.instance.PlayerProfile.BatchResourceUpdate(combineResult.Produced);
			GameWorld.instance.PlayerProfile.ReceiveEvent(GameWorldEvent.ItemCombined, combineResult);
		}
		return combineResult.Produced;
	}

public static List<ResourceUpdate> BatchCombine_Equipment(List<Item> items)
	{
		List<Item> source = (from i in items
			where i.Type.GetResourceCategory().IsWeapon() || i.Type.GetResourceCategory().IsArmor() || i.Type.GetResourceCategory() == ResourceCategory.Gem
			select (i)).ToList();
		var list = (from t in source
			group t by t.Level into g
			where g.Count() >= 3
			select new
			{
				Level = g.Key,
				Items = g.ToList()
			} into l
			orderby l.Level
			select l).ToList();
		double num = 0.0;
		List<ResourceUpdate> list2 = new List<ResourceUpdate>();
		List<Item> list3 = new List<Item>();
		bool flag = true;
		foreach (var item in list)
		{
			if (!flag)
			{
				continue;
			}
			var list4 = (from i in item.Items
				group i by i.Type into i
				where i.Count() >= 3
				select new
				{
					Type = i.Key,
					Items = i.Where((Item it) => it.ItemGrade < QualityGrade.Ancient).ToList()
				}).ToList();
			foreach (var item2 in list4)
			{
				List<Item> list5 = item2.Items.Select((Item i) => i).ToList();
				List<IGrouping<QualityGrade, Item>> list6 = (from g in list5
					group g by g.ItemGrade into g
					where g.Count() >= 3
					select g).ToList();
				while (list6.Any() && flag)
				{
					foreach (IGrouping<QualityGrade, Item> item3 in list6)
					{
						List<Item> tocombine = item3.Take(3).ToList();
						if (GameWorld.instance.PlayerProfile.CanAfford(num + GetCombineCost(tocombine)))
						{
							CombineResult combineResult = CalculateCombineResult(tocombine);
							list2.AddRange(combineResult.Produced);
							list5.AddRange(combineResult.Produced.SelectMany((ResourceUpdate i) => i.RelatedItems.Where((Item it) => it.ItemGrade != QualityGrade.Ancient)));
							num += GetCombineCost(tocombine);
							list5.RemoveAll((Item i) => tocombine.Any((Item it) => it == i));
							list3.AddRange(tocombine);
						}
						else
						{
							flag = false;
						}
					}
					list6 = (from g in list5
						group g by g.ItemGrade into g
						where g.Count() >= 3
						select g).ToList();
				}
			}
		}
		List<ResourceUpdate> changes = list3.Select((Item i) => new ResourceUpdate
		{
			ResourceType = i.Type,
			ChangeAmount = -1.0,
			RelatedItems = new List<Item> { i }
		}).ToList();
		GameWorld.instance.PlayerProfile.SpendMoney(num);
		GameWorld.instance.PlayerProfile.BatchResourceUpdate(list2);
		GameWorld.instance.PlayerProfile.BatchResourceUpdate(changes);
		return list2;
	}

public static List<ResourceUpdate> BatchCombine_Gem(List<Item> items)
	{
		List<Item> source = (from result in items
			where result.Type.GetResourceCategory() == ResourceCategory.Gem
			select (result)).ToList();
		var source2 = (from t in source
			group t by t.Level into g
			select new
			{
				Level = g.Key,
				Items = g.ToList()
			} into l
			orderby l.Level
			select l).ToList();
		List<LevelGoupedItems> list = new List<LevelGoupedItems>();
		int i;
		for (i = 1; i < ItemExtensions.MaxGemLevel; i++)
		{
			var anon = source2.FirstOrDefault(l => l.Level == i);
			if (anon != null)
			{
				list.Add(new LevelGoupedItems
				{
					Items = anon.Items,
					Level = i
				});
			}
			else
			{
				list.Add(new LevelGoupedItems
				{
					Items = new List<Item>(),
					Level = i
				});
			}
		}
		double num = 0.0;
		List<ResourceUpdate> list2 = new List<ResourceUpdate>();
		List<Item> list3 = new List<Item>();
		bool flag = true;
		for (int num2 = 1; num2 < ItemExtensions.MaxGemLevel; num2++)
		{
			LevelGoupedItems levelGoupedItems = list[num2 - 1];
			if (!flag)
			{
				continue;
			}
			var list4 = (from item in levelGoupedItems.Items
				group item by item.Type into grouping
				where grouping.Count() >= 3
				select new
				{
					Type = grouping.Key,
					Items = grouping.ToList()
				}).ToList();
			foreach (var item in list4)
			{
				List<Item> list5 = item.Items.Select((Item result) => result).ToList();
				while (list5.Count >= 3 && flag)
				{
					List<Item> tocombine = list5.Take(3).ToList();
					if (GameWorld.instance.PlayerProfile.CanAfford(num + GetCombineCost(tocombine)))
					{
						CombineResult combineResult = CalculateCombineResult(tocombine);
						list2.AddRange(combineResult.Produced);
						if (levelGoupedItems.Level + 1 < ItemExtensions.MaxGemLevel)
						{
							list[levelGoupedItems.Level].Items.AddRange(combineResult.Produced.SelectMany((ResourceUpdate resourceUpdate) => resourceUpdate.RelatedItems));
						}
						num += GetCombineCost(tocombine);
						list5.RemoveAll((Item item) => tocombine.Any((Item it) => it == item));
						list3.AddRange(tocombine);
					}
					else
					{
						flag = false;
					}
				}
			}
		}
		List<ResourceUpdate> changes = list3.Select((Item item) => new ResourceUpdate
		{
			ResourceType = item.Type,
			ChangeAmount = -1.0,
			RelatedItems = new List<Item> { item }
		}).ToList();
		GameWorld.instance.PlayerProfile.SpendMoney(num);
		GameWorld.instance.PlayerProfile.BatchResourceUpdate(list2);
		GameWorld.instance.PlayerProfile.BatchResourceUpdate(changes);
		return list2;
	}

public static CombineResult CalculateCombineResult(List<Item> items)
	{
		CombineResult combineResult = new CombineResult();
		combineResult.Consumed = new List<ResourceUpdate>();
		combineResult.Produced = new List<ResourceUpdate>();
		CombineResult combineResult2 = combineResult;
		if (items.IsCombineable() && GameWorld.instance.PlayerProfile.CanAfford(GetCombineCost(items)))
		{
			if (items.First().Type.GetResourceCategory() == ResourceCategory.Gem)
			{
				int num = items.First().Level + 1;
				if (num <= ItemExtensions.MaxGemLevel)
				{
					ResourceType type = items[0].Type;
					combineResult2.Consumed = new List<ResourceUpdate>
					{
						new ResourceUpdate
