public override AttributeType GeneratePrimaryAttributeType(ResourceType pieceType)
	{
		return pieceType switch
		{
			ResourceType.CircleOfFocus => AttributeType.CritDamage, 
			ResourceType.WheelOfFocus => AttributeType.Agility, 
			ResourceType.SpikeOfFocus => (!((double)UnityEngine.Random.value <= 0.5)) ? AttributeType.Strength : AttributeType.Intelligience, 
			_ => AttributeType.None, 
		};
	}

