public void EnchantEffectForScroll(Item anotherItem, List<ISpecialEffectDataLoad> effects)
	{
		if (Type.GetResourceCategory() == ResourceCategory.Scrolls && anotherItem.Level >= 8 && (anotherItem.Type.GetResourceCategory().IsWeapon() || anotherItem.Type.GetResourceCategory().IsArmor()) && GetEffectEnchantingCost().MetRequirements())
		{
			if (effects.All((ISpecialEffectDataLoad ef) => anotherItem.GetSpecialEffects().Any((ISpecialEffectDataLoad ane) => ane == ef)))
			{
				List<ResourceUpdate> list = (from c in GetEffectEnchantingCost()
					select new ResourceUpdate
					{
						ResourceType = c.ResourceType,
						ChangeAmount = -c.AmountRequired,
						RelatedItems = new List<Item>()
					}).ToList();
				list.Add(new ResourceUpdate
				{
					ResourceType = anotherItem.Type,
					ChangeAmount = -1.0,
					RelatedItems = new List<Item> { anotherItem }
				});
				AddedSpecialEffects = effects;
				GameWorld.instance.PlayerProfile.BatchResourceUpdate(list);
			}
		}
		else
		{
			if (!IsEffectReplacementUsable() || !anotherItem.IsEffectReplacementUsable() || !GetEffectEnchantingCost().MetRequirements() || !effects.All((ISpecialEffectDataLoad ef) => anotherItem.GetSpecialEffects().Any((ISpecialEffectDataLoad ane) => ane == ef)))
			{
				return;
			}
			List<ResourceUpdate> list2 = (from c in GetEffectEnchantingCost()
				select new ResourceUpdate
				{
					ResourceType = c.ResourceType,
					ChangeAmount = -c.AmountRequired,
					RelatedItems = new List<Item>()
				}).ToList();
			list2.Add(new ResourceUpdate
			{
				ResourceType = anotherItem.Type,
				ChangeAmount = -1.0,
				RelatedItems = new List<Item> { anotherItem }
			});
			if (effects.Any((ISpecialEffectDataLoad e) => e.IsStarEffect()))
			{
				SpecialEffects.RemoveAll((ISpecialEffectDataLoad e) => e.IsStarEffect());
				IsStarGear = true;
			}
			else
			{
				SpecialEffects.RemoveAll((ISpecialEffectDataLoad e) => !e.IsStarEffect());
			}
			SpecialEffects.AddRange(effects);
			GameWorld.instance.PlayerProfile.BatchResourceUpdate(list2);
		}
	}

