public List<AttributeModifier> Reforging()
	{
		if (IsReforgeable() && GetReforgingCost().MetRequirements())
		{
			StartReforgeGenerationScope();
			List<ResourceUpdate> changes = (from s in GetReforgingCost()
				select new ResourceUpdate
				{
					ResourceType = s.ResourceType,
					ChangeAmount = -s.AmountRequired,
					RelatedItems = new List<Item>()
				}).ToList();
			GameWorld.instance.PlayerProfile.BatchResourceUpdate(changes);
			List<ItemPropertyPotential> reforgePotentialAttributes = GetReforgePotentialAttributes();
			HasBeenReforgedForTimes = GetNumberOfReforgedTimes() + 1;
			List<AttributeModifier> list = new List<AttributeModifier>();
			for (int num = 0; num < 3; num++)
			{
				ItemPropertyPotential itemPropertyPotential = reforgePotentialAttributes[UnityEngine.Random.Range(0, reforgePotentialAttributes.Count)];
				list.Add(ItemExtensions.RandomGenerateAttributeModifier_Reforging(Convert.ToSingle(itemPropertyPotential.Mean), itemPropertyPotential.ModificationType, itemPropertyPotential.AttributeType));
			}
			CurrentReforgeAttributeSelections = list;
			RotateReforgeGeneration();
			return list;
		}
		return new List<AttributeModifier>();
	}

public List<List<AttributeModifier>> Enchanting()
	{
		if (IsEnchantable() && GetEnchantingCost().MetRequirements())
		{
			StartEnchantingGenerationScope();
			List<ResourceUpdate> changes = (from c in GetEnchantingCost()
				select new ResourceUpdate
				{
					ResourceType = c.ResourceType,
					ChangeAmount = -c.AmountRequired,
					RelatedItems = new List<Item>()
				}).ToList();
			GameWorld.instance.PlayerProfile.BatchResourceUpdate(changes);
			List<ItemPropertyPotential> enchantableAttributes = GetEnchantableAttributes();
			HasBeenEnchantedForTimes = GetNumberOfEnchantedTimes() + 1;
			int count = ((!IsStarItem()) ? 1 : 2);
			List<List<AttributeModifier>> list = new List<List<AttributeModifier>>();
			for (int num = 0; num < 3; num++)
			{
				enchantableAttributes.Shuffle();
				List<ItemPropertyPotential> source = enchantableAttributes.Take(count).ToList();
				list.Add(source.Select((ItemPropertyPotential p) => ItemExtensions.RandomGenerateAttributeModifier_Enchanting(Convert.ToSingle(p.Mean), p.ModificationType, p.AttributeType)).ToList());
			}
			CurrentEnchantedAttributeSelections = list;
			RotateEnchantingGeneration();
			return list;
		}
		return new List<List<AttributeModifier>>();
	}

