		{
			return;
		}
		List<AttributeModifier> list = AdditionalAttributeModifiers.Where((AttributeModifier a) => a.Key == "enchanted").ToList();
		foreach (AttributeModifier item in list)
		{
			AdditionalAttributeModifiers.Remove(item);
