public void Socket(Item gem)
	{
		SocketType? gemSocketType = gem.GetGemSocketType();
		if (gem.Type.GetResourceCategory() != ResourceCategory.Gem || !gemSocketType.HasValue || !CanBeSocketedWith(gem))
		{
			return;
		}
		ItemSocket itemSocket = Sockets.FirstOrDefault((ItemSocket s) => s.SocketType == gemSocketType.Value && s.IsEmptySocket());
		if (itemSocket != null)
		{
			itemSocket.Gem = gem;
			GameWorld.instance.PlayerProfile.BatchResourceUpdate(new List<ResourceUpdate>
			{
				new ResourceUpdate
				{
					ResourceType = gem.Type,
					ChangeAmount = -1.0,
					RelatedItems = new List<Item> { gem }
				}
			});
		}
		else
		{
			ItemSocket itemSocket2 = Sockets.FirstOrDefault((ItemSocket s) => s.SocketType == SocketType.All && s.IsEmptySocket());
			if (itemSocket2 != null)
			{
				itemSocket2.Gem = gem;
				GameWorld.instance.PlayerProfile.BatchResourceUpdate(new List<ResourceUpdate>
				{
					new ResourceUpdate
					{
						ResourceType = gem.Type,
						ChangeAmount = -1.0,
						RelatedItems = new List<Item> { gem }
					}
				});
			}
		}
		CalculateQualityRatingsAndCacheAttributes();
	}

