public static Item ItemGenerate(this ResourceType type, ResourceSourceType itemSource, ItemGenerationQuality quality, int itemTierLevel, int level = 1)
	{
		ResourceCategory resourceCategory = type.GetResourceCategory();
		switch (resourceCategory)
		{
		case ResourceCategory.Gem:
		{
			GameWorld.instance.PlayerProfile.StartGenerationSeedScope(type);
			Item item5 = CreateGem(type, level);
			GameWorld.instance.PlayerProfile.RotateSeed(type);
			item5.CalculateQualityRatingsAndCacheAttributes();
			return item5;
		}
		case ResourceCategory.Usable:
		{
			Item item = new Item();
			item.Value = 500 + level * 500;
			item.Level = level;
			item.Type = type;
			item.ItemGrade = QualityGrade.Ancient;
			item.Id = Guid.NewGuid().ToString();
			item.ItemStatus = ItemStatus.Reserved;
			item.AdditionalAttributeModifiers = new List<AttributeModifier>();
			item.PrimaryAttributeModifiers = new List<AttributeModifier>();
			item.SlotType = ItemType.Normal;
			item.SpecialEffects = new List<ISpecialEffectDataLoad>();
			item.AddedSpecialEffects = new List<ISpecialEffectDataLoad>();
			item.PurchasedOnTime = GameWorld.instance.PlayerProfile.GameDaysFractional;
			item.Sockets = new List<ItemSocket>();
			item.IsStarGear = false;
			item.HasBeenEnchantedForTimes = 0;
			item.ItemTierLevel = level * 5 - 4;
			item.CanBeReforged = false;
			return item;
		}
		case ResourceCategory.Device:
		{
			GameWorld.instance.PlayerProfile.StartGenerationSeedScope(type);
			Item item8 = GenerateDevice(type, itemTierLevel);
			GameWorld.instance.PlayerProfile.RotateSeed(type);
			item8.CalculateQualityRatingsAndCacheAttributes();
			return item8;
		}
		case ResourceCategory.Scrolls:
		{
			GameWorld.instance.PlayerProfile.StartGenerationSeedScope(type);
			Item item6 = GenerateScroll(type, quality.IsStar, itemTierLevel);
			GameWorld.instance.PlayerProfile.RotateSeed(type);
			item6.CalculateQualityRatingsAndCacheAttributes();
			return item6;
		}
		case ResourceCategory.Amulet:
		{
			TeamSetBase teamSetBase = type.GetTeamSetBase();
			GameWorld.instance.PlayerProfile.StartGenerationSeedScope(type);
			AttributeType attributeType = teamSetBase.GeneratePrimaryAttributeType(type);
			Item item = new Item();
			item.ItemGrade = QualityGrade.Normal;
			item.Value = 1000.0;
			item.Id = Guid.NewGuid().ToString();
			item.ItemStatus = ItemStatus.Reserved;
			item.Type = type;
			item.AdditionalAttributeModifiers = new List<AttributeModifier>();
			item.PrimaryAttributeModifiers = new List<AttributeModifier>();
			item.SlotType = (resourceCategory.IsWeapon() ? ItemType.Weapon : (resourceCategory.IsArmor() ? ItemType.Armor : (resourceCategory switch
			{
				ResourceCategory.Accessory => ItemType.Accessory, 
				ResourceCategory.Amulet => ItemType.Amulet, 
				_ => ItemType.None, 
			})));
			item.Level = 0;
			item.SpecialEffects = new List<ISpecialEffectDataLoad>();
			item.AddedSpecialEffects = new List<ISpecialEffectDataLoad>();
			item.PurchasedOnTime = GameWorld.instance.PlayerProfile.GameDaysFractional;
			item.Sockets = new List<ItemSocket>();
			item.IsStarGear = false;
			item.HasBeenEnchantedForTimes = 0;
			item.ItemTierLevel = 0;
			item.CanBeReforged = false;
			item.PotentialTeamPieceEffects = teamSetBase.GetPotentialEffectTypes(teamSetBase.GetItemSuitableClassType(type));
			item.PotentialTeamUpgradeAttributes = new List<AttributeType>();
			item.OutputTypeForTeamSet = ((attributeType == AttributeType.Intelligience || attributeType == AttributeType.Strength) ? attributeType : ((!((double)UnityEngine.Random.value <= 0.5)) ? AttributeType.Strength : AttributeType.Intelligience));
			item.TeamSetUpgradeMarker = string.Empty;
			item.TeamSetPiecePrimaryAttributeType = attributeType;
			item.TeamSetSeed = UnityEngine.Random.Range(1, 100000);
			Item item7 = item;
			item7.PotentialTeamUpgradeAttributes = teamSetBase.GetPotentialRollAttributeTypes(item7);
			teamSetBase.Upgrade(item7, 0);
			GameWorld.instance.PlayerProfile.RotateSeed(type);
			foreach (ISpecialEffectDataLoad teamBonu in teamSetBase.GetTeamBonus())
			{
				GameWorld.instance.PlayerProfile.UnlockEffect(teamBonu.GetSpecialEffectType());
			}
			item7.CalculateQualityRatingsAndCacheAttributes();
			return item7;
		}
		default:
		{
			ItemTemplateBase itemTemplateBase = BuildingExtensions.ItemTemplates[type];
			QualityGrade grade = quality.QualityGrade;
			int itemTier = itemTierLevel;
			Item item;
