		List<AttributeModifier> list4 = new List<AttributeModifier>();
		foreach (AttributeType item2 in list3)
		{
			double num = new AttributePotentialDescriptor(item2, AttributePowerLevel.Medium, AttributeStyle.Beneficial).GetMean(root, AttributeGrade.Secondary);
			if (item2 == AttributeType.EffectMastery)
			{
				num = 0.8;
			}
			double value = num * (double)UnityEngine.Random.Range(0.5f, 1f);
			list4.Add(new AttributeModifier
			{
				AttributeType = item2,
				ModificationType = ModificationType.Addition,
				Value = value,
				Key = string.Empty,
				AttributeModifierType = AttributeModifierType.Gear
			});
		}
		List<ItemSocket> list5 = new List<ItemSocket>();
		list5.Add(new ItemSocket
		{
			SocketType = SocketType.All,
			Gem = new NullObject(),
			SourceType = SocketSourceType.SystemGenerated
		});
		List<ItemSocket> sockets = list5;
		List<ISpecialEffectDataLoad> list6 = new List<ISpecialEffectDataLoad>();
		if (isStar)
		{
			list6 = GenerateScrollEffects(type);
		}
		foreach (ISpecialEffectDataLoad item3 in list6)
		{
			GameWorld.instance.PlayerProfile.UnlockEffect(item3.GetSpecialEffectType());
		}
		Item item = new Item();
		item.ItemGrade = QualityGrade.Ancient;
		item.Value = 1000.0;
		item.Id = Guid.NewGuid().ToString();
		item.ItemStatus = ItemStatus.Reserved;
		item.Type = type;
		item.AdditionalAttributeModifiers = list4.OrderBy((AttributeModifier a) => a.AttributeType).ToList();
		item.PrimaryAttributeModifiers = new List<AttributeModifier>();
		item.SlotType = ItemType.Scroll;
		item.Level = (int)Math.Ceiling((double)itemTierLevel / 5.0);
		item.SpecialEffects = list6;
		item.PurchasedOnTime = GameWorld.instance.PlayerProfile.GameDaysFractional;
		item.Sockets = sockets;
		item.IsStarGear = isStar;
		item.ItemTierLevel = itemTierLevel;
		item.HasBeenEnchantedForTimes = 0;
		item.AddedSpecialEffects = new List<ISpecialEffectDataLoad>();
		item.CanBeReforged = false;
		return item;
	}

