		dictionary.Add(QualityGrade.Normal, new List<GemSocketNumberPresentable>
		{
			new GemSocketNumberPresentable(100, 0)
		});
		dictionary.Add(QualityGrade.Rare, new List<GemSocketNumberPresentable>
		{
			new GemSocketNumberPresentable(80, 0),
			new GemSocketNumberPresentable(20, 1)
		});
		dictionary.Add(QualityGrade.Epic, new List<GemSocketNumberPresentable>
		{
			new GemSocketNumberPresentable(50, 0),
			new GemSocketNumberPresentable(50, 1)
		});
		dictionary.Add(QualityGrade.Legendary, new List<GemSocketNumberPresentable>
		{
			new GemSocketNumberPresentable(80, 1),
			new GemSocketNumberPresentable(20, 2)
		});
		dictionary.Add(QualityGrade.Ancient, new List<GemSocketNumberPresentable>
		{
			new GemSocketNumberPresentable(100, 2)
		});
		Dictionary<QualityGrade, List<GemSocketNumberPresentable>> dictionary2 = dictionary;
		List<ItemSocket> list = new List<ItemSocket>();
		int num = ((type.GetResourceCategory() != ResourceCategory.Accessory) ? dictionary2[grade].WeightedRandomSelect().NumberOfSockets : 0);
		for (int i = 0; i < num; i++)
		{
			if (grade == QualityGrade.Ancient && i == 0)
			{
				list.Add(new ItemSocket
				{
					SocketType = SocketType.All,
					Gem = new NullObject(),
					SourceType = SocketSourceType.SystemGenerated
				});
			}
			else
			{
				list.Add(new ItemSocket
				{
					SocketType = SocketType.All,
					Gem = new NullObject(),
					SourceType = SocketSourceType.SystemGenerated
				});
			}
		}
		return list;
	}

