private static GenerationIntrimResult GenerateProperties(QualityGrade grade, int totalPotentialProperties, List<ItemPropertyPotential> potentials)
	{
		List<AttributeModifier> list = new List<AttributeModifier>();
		foreach (ItemPropertyPotential item3 in potentials.Where((ItemPropertyPotential p) => p.IsGuaranteed))
		{
			double gradedAttributeValue = GetGradedAttributeValue(item3.AttributeType, grade, Convert.ToSingle(item3.Mean));
			AttributeModifier item = RandomGenerateAttributeModifier_ItemGeneration(Convert.ToSingle(gradedAttributeValue), item3.ModificationType, item3.AttributeType, item3.AttributeGrade);
			list.Add(item);
		}
		int num = totalPotentialProperties;
		List<ItemPropertyPotential> list2 = potentials.Where((ItemPropertyPotential p) => !p.IsGuaranteed).ToList();
		while (num > 0 && list2.Any())
		{
			list2.Shuffle();
			foreach (ItemPropertyPotential item4 in list2)
			{
				if (num > 0)
				{
					double gradedAttributeValue2 = GetGradedAttributeValue(item4.AttributeType, grade, Convert.ToSingle(item4.Mean));
					AttributeModifier item2 = RandomGenerateAttributeModifier_ItemGeneration(Convert.ToSingle(gradedAttributeValue2), item4.ModificationType, item4.AttributeType, item4.AttributeGrade);
					list.Add(item2);
					num--;
				}
			}
		}
		GenerationIntrimResult generationIntrimResult = new GenerationIntrimResult();
		generationIntrimResult.AttributeModifiers = list;
		generationIntrimResult.UsedPotentialModifiers = totalPotentialProperties;
		return generationIntrimResult;
	}

public static AttributeModifier RandomGenerateAttributeModifier_ItemGeneration(float mean, ModificationType modificationType, AttributeType attributeType, AttributeGrade grade)
	{
		AttributeModifier attributeModifier;
		if (mean >= 0f)
		{
			attributeModifier = new AttributeModifier();
			attributeModifier.AttributeType = attributeType;
			attributeModifier.ModificationType = modificationType;
			attributeModifier.Value = UnityEngine.Random.Range(mean * (1f - ItemAttributeRandomness_Generation), mean * (1f + ItemAttributeRandomness_Generation));
			attributeModifier.AttributeModifierType = AttributeModifierType.Gear;
			attributeModifier.Key = "generation_" + grade;
			return attributeModifier;
		}
		attributeModifier = new AttributeModifier();
		attributeModifier.AttributeType = attributeType;
		attributeModifier.ModificationType = modificationType;
		attributeModifier.Value = UnityEngine.Random.Range(mean * (1f + ItemAttributeRandomness_Generation), mean * (1f - ItemAttributeRandomness_Generation));
		attributeModifier.AttributeModifierType = AttributeModifierType.Gear;
		attributeModifier.Key = "generation_" + grade;
		return attributeModifier;
	}

