public static List<ItemRoot> GenerateRoots(List<AttributeType> mainAttributes, List<AttributeType> minorAttributes, List<double> means)
	{
		if (mainAttributes.Any((AttributeType a) => minorAttributes.Any((AttributeType m) => m == a)))
		{
			throw new Exception("Invalid attributes: duplicated attributes");
		}
		List<AttributeType> allAttributeTypes = ItemExtensions.AllAttributeTypes;
		if (!allAttributeTypes.All((AttributeType t) => mainAttributes.Any((AttributeType m) => m == t) || minorAttributes.Any((AttributeType m) => m == t) || t == AttributeType.None))
		{
			List<AttributeType> source = allAttributeTypes.Where((AttributeType t) => mainAttributes.All((AttributeType m) => m != t) && minorAttributes.All((AttributeType m) => m != t)).ToList();
			throw new Exception("Invalid attributes: incomplete list: " + string.Join(", ", source.Select((AttributeType m) => m.ToString()).ToArray()));
		}
		List<ItemRoot> list = new List<ItemRoot>();
		for (int num = 0; num < means.Count; num++)
		{
			ItemRoot itemRoot = new ItemRoot();
			itemRoot.RootAdditionModifiers = new List<AttributeModifier>();
			itemRoot.CorrespondingItemTier = num + 1;
			itemRoot.Workload = ((num >= 35) ? (1800 + (num - 35) * 20) : ((num + 1) * 60));
			itemRoot.PriceBase = 50 + (num + 1) * 5;
			ItemRoot itemRoot2 = itemRoot;
			foreach (AttributeType mainAttribute in mainAttributes)
			{
				itemRoot2.RootAdditionModifiers.Add(new AttributeModifier
				{
					AttributeType = mainAttribute,
					Value = GetAttributeMean(mainAttribute, means[num], num + 1),
					ModificationType = ModificationType.Addition,
					AttributeModifierType = AttributeModifierType.Normal
				});
			}
			foreach (AttributeType minorAttribute in minorAttributes)
			{
				itemRoot2.RootAdditionModifiers.Add(new AttributeModifier
				{
					AttributeType = minorAttribute,
					Value = GetAttributeMean(minorAttribute, means[num], num + 1) / 2.0,
					ModificationType = ModificationType.Addition,
					AttributeModifierType = AttributeModifierType.Normal
				});
			}
			list.Add(itemRoot2);
		}
		return list;
	}

private static double GetAttributeMean(AttributeType type, double normalMean, int itemTier)
	{
		if (type.IsCoreAttributes())
		{
			switch (type)
			{
			case AttributeType.CritDamage:
				if (itemTier <= 50)
				{
					return 0.6;
				}
				return 1.6;
			case AttributeType.CritRate:
				if (itemTier <= 40)
				{
					return 0.3;
				}
				return 0.6;
			case AttributeType.Vitality:
				return normalMean * 1.8;
			default:
				if (type.IsResistanceAttribute())
				{
					return normalMean * 2.8;
				}
				if (type == AttributeType.Allresistances)
				{
					return normalMean * 2.8;
				}
				return normalMean;
			}
		}
		switch (type)
		{
		case AttributeType.LifeOnHit:
			return 0.1;
		case AttributeType.TauntOnHit:
			if (itemTier <= 45)
			{
				return 0.2;
			}
			return 0.4;
		case AttributeType.StunOnHit:
			return 0.3;
		case AttributeType.ReflectiveDamage:
			if (itemTier <= 35)
			{
				return 0.6;
			}
			if (itemTier <= 50)
			{
				return 1.2;
			}
			return 2.0;
		case AttributeType.BattleStartHeal:
			return 0.2;
		case AttributeType.TurnStartHeal:
			return 0.12;
		case AttributeType.Mining:
			if (itemTier <= 40)
			{
				return 1.0;
			}
			return 2.0;
		case AttributeType.Logging:
			if (itemTier <= 40)
			{
				return 1.0;
			}
			return 2.0;
		case AttributeType.Hunting:
			if (itemTier <= 40)
			{
				return 1.0;
			}
			return 2.0;
		case AttributeType.ReceivedHealEffectivenessChangeRate:
			return 0.2;
		case AttributeType.DealFireDamageEffectivenessChangeRate:
		case AttributeType.DealPhysicalDamageEffectivenessChangeRate:
		case AttributeType.DealIceDamageEffectivenessChangeRate:
		case AttributeType.DealShadowDamageEffectivenessChangeRate:
		case AttributeType.DealPoisonDamageEffectivenessChangeRate:
		case AttributeType.DealDivineDamageEffectivenessChangeRate:
		case AttributeType.DealLightningDamageEffectivenessChangeRate:
			if (itemTier <= 45)
			{
				return 0.4;
			}
			return 0.7;
		case AttributeType.Resilience:
			return normalMean;
		case AttributeType.DamageReduction:
			return 0.2;
		case AttributeType.SkillRageEfficiencyRate:
			if (itemTier <= 45)
			{
				return 0.1;
			}
			return 0.2;
		case AttributeType.HealingAbsorbRate:
			return 0.1;
		case AttributeType.EffectMastery:
			return 0.2;
		case AttributeType.HitRateAdjustment:
			return 0.15;
		case AttributeType.DodgeRateAdjustment:
			return 0.15;
		case AttributeType.EffectHitRating:
		case AttributeType.EffectResistanceRating:
			if (itemTier <= 40)
			{
				return 100.0;
			}
			if (itemTier <= 50)
			{
				return 200.0;
			}
			return 300.0;
		case AttributeType.PhysicalPenetration:
		case AttributeType.FirePenetration:
		case AttributeType.IcePenetration:
		case AttributeType.ShadowPenetration:
		case AttributeType.PoisonPenetration:
		case AttributeType.DivinePenetration:
		case AttributeType.LighteningPenetration:
			return 0.3;
		default:
			throw new ArgumentOutOfRangeException("type", type, null);
		}
	}

