private int GetCurrentProductItemTier()
	{
		if (_itemTierLevel.HasValue)
		{
			return _itemTierLevel.Value;
		}
		if (_currentWorkingItemDifficultyValue.HasValue)
		{
			return DifficultyLevelMeasurement.GetDifficultyLevelMeasurementByValue(_currentWorkingItemDifficultyValue.Value, 1).GetCorrespondingItemTierLevel(_currentWorkingItem.ProductType);
		}
		return GameWorld.instance.PlayerProfile.GetDifficultyLevelMeasurement_OneStar().GetCorrespondingItemTierLevel(_currentWorkingItem.ProductType);
	}

public void Enqueue(ResourceType job, int itemTierLevel, int quantity)
	{
		RecipeInfo recipeInfo = GetCapableRecipes().FirstOrDefault((RecipeInfo r) => r.Recipe.ProductType == job);
		if (recipeInfo != null && recipeInfo.Recipe.MetRequirement(quantity, itemTierLevel))
		{
			WorkQueue workQueue = WorkQueues.LastOrDefault();
			if (workQueue == null || workQueue.ProductType != job || workQueue.ProductType == job)
			{
				WorkQueue workQueue2 = new WorkQueue();
				workQueue2.ProductType = recipeInfo.Recipe.ProductType;
				workQueue2.Quantity = quantity;
				workQueue2.ItemTierLevel = itemTierLevel;
				WorkQueue item = workQueue2;
				WorkQueues.Add(item);
			}
			else
			{
				workQueue.Quantity += quantity;
			}
			GameWorld.instance.PlayerProfile.BatchResourceUpdate((from r in recipeInfo.Recipe.GetProductionRequirements(itemTierLevel)
				select new ResourceUpdate
				{
					ResourceType = r.ResourceType,
					ChangeAmount = -r.AmountRequired * quantity,
					RelatedItems = new List<Item>()
				}).ToList());
			OnNewQueue(recipeInfo.Recipe, quantity);
		}
		else
		{
			UnityEngine.Debug.LogError("Cannot find recipe for " + job);
		}
	}

public void Dequeue(int index)
	{
		if (WorkQueues.Count >= index + 1)
		{
			WorkQueue tobeRemoved = WorkQueues[index];
			WorkQueues.RemoveAt(index);
			Recipe recipeByProductType = tobeRemoved.ProductType.GetRecipeByProductType();
			List<ResourceConsumptionRequirement> productionRequirements = recipeByProductType.GetProductionRequirements(tobeRemoved.GetItemTierLevel());
			List<ResourceUpdate> changes = productionRequirements.Select((ResourceConsumptionRequirement r) => new ResourceUpdate
			{
				ResourceType = r.ResourceType,
				ChangeAmount = r.AmountRequired * tobeRemoved.Quantity,
				RelatedItems = new List<Item>()
			}).ToList();
			GameWorld.instance.PlayerProfile.BatchResourceUpdate(changes);
			OnQueueRemoved(tobeRemoved);
		}
	}

private void UpdateCurrentWorkloadGenerated(double nvalue)
	{
		_currentWorkloadGenerated = nvalue;
		OnProgressChanged(GetProgress());
	}

public void Process(float timeDelta)
	{
		if (GameWorld.instance.PlayerProfile.IsInventoryFull())
		{
			return;
		}
		timeDelta *= PlayerProfile.ProcessSpeed;
		if (_currentWorkingItem != null)
		{
			double finalProductionRate = BuildingExtensions.GetFinalProductionRate(this);
			double nvalue = _currentWorkloadGenerated + finalProductionRate * (double)timeDelta;
			UpdateCurrentWorkloadGenerated(nvalue);
			if (!(_currentWorkloadGenerated >= _currentWorkingItem.GetWorkload(GetCurrentProductItemTier())))
			{
				return;
			}
			Product product = _currentWorkingItem.Produce(GetCurrentProductItemTier());
			OnCompletesOnQueueRecipe(_currentWorkingItem, product);
			_numberOfWorksToBePerformed--;
			if (product.Success)
			{
				GameWorld.instance.PlayerProfile.ReceiveEvent(GameWorldEvent.ItemProduced, product);
				if (product.RelatedItems.Any((Item i) => i.ItemGrade == QualityGrade.Epic))
				{
					GameWorld.instance.PlayerProfile.ReceiveEvent(GameWorldEvent.EpicItemProduced, product);
				}
				if (product.RelatedItems.Any((Item i) => i.ItemGrade == QualityGrade.Ancient))
				{
					GameWorld.instance.PlayerProfile.ReceiveEvent(GameWorldEvent.AncientItemProduced, product);
				}
				if (product.RelatedItems.Any((Item i) => i.ItemGrade == QualityGrade.Epic))
				{
					GameWorld.instance.PlayerProfile.ReceiveEvent(GameWorldEvent.LengendaryItemProduced, product);
				}
			}
			if (_numberOfWorksToBePerformed == 0)
			{
				_currentWorkingItem = null;
				TryPickupQueue(hasPreviousWork: true);
			}
			else
			{
				UpdateCurrentWorkloadGenerated(0.0);
			}
		}
		else
		{
			TryPickupQueue(hasPreviousWork: false);
		}
	}

private void TryPickupQueue(bool hasPreviousWork)
	{
		if (WorkQueues.Any())
		{
			_currentWorkingItem = GetCapableRecipes().FirstOrDefault((RecipeInfo r) => r.Recipe.ProductType == WorkQueues.First().ProductType)?.Recipe;
			_currentWorkingItemDifficultyValue = WorkQueues.First().RelatedDifficultyValue;
			_itemTierLevel = WorkQueues.First().GetItemTierLevel();
			_numberOfWorksToBePerformed = WorkQueues.First().Quantity;
			UpdateCurrentWorkloadGenerated(0.0);
			WorkQueues.RemoveAt(0);
			OnStartsOnQueueRecipe(_currentWorkingItem);
			if (!hasPreviousWork)
			{
				OnBuildingStateChanges(BuildingState.Idle, BuildingState.Working);
			}
		}
		else if (hasPreviousWork)
		{
			OnBuildingStateChanges(BuildingState.Working, BuildingState.Idle);
		}
	}

public void ResetCurrentProduction()
	{
		UpdateCurrentWorkloadGenerated(0.0);
		GameWorld.instance.PlayerProfile.BatchResourceUpdate((from r in _currentWorkingItem.GetProductionRequirements(GetCurrentProductItemTier())
			select new ResourceUpdate
			{
				ResourceType = r.ResourceType,
				ChangeAmount = r.AmountRequired * _numberOfWorksToBePerformed,
				RelatedItems = new List<Item>()
			}).ToList());
		_numberOfWorksToBePerformed = 0;
		_currentWorkingItem = null;
		OnBuildingStateChanges(BuildingState.Working, BuildingState.Idle);
	}

public List<RecipeInfo> GetCapableRecipes()
	{
		DifficultyLevelMeasurement playerMeasurement = GameWorld.instance.PlayerProfile.GetProductionDifficultyLevelMeasurement();
		List<Recipe> source = (from r in BuildingExtensions.Recipes
			where r.BuildingType == _buildingType
			where GameWorld.instance.PlayerProfile.RecipeHasAccaquired(r.ProductType)
			select r).ToList();
		List<RecipeInfo> list = new List<RecipeInfo>();
		if (source.Any())
		{
			int correspondingItemTierLevel = playerMeasurement.GetCorrespondingItemTierLevel(source.First().ProductType);
			int currentTier = correspondingItemTierLevel;
			while (currentTier > 35)
			{
				list.AddRange(from r in source
					where r.ProductType.GetCreationTemplate().ExtraGuarranteedSecondaryGradedAttributes(playerMeasurement.GetCorrespondingItemTierLevel(r.ProductType)).Any() || r.ProductType.GetCreationTemplate().AdditionalGuarranteedPrimaryGradedAttributes(playerMeasurement.GetCorrespondingItemTierLevel(r.ProductType)).Any()
					select new RecipeInfo
					{
						Recipe = r,
						IsQuestRelevant = false,
						ItemTierLevel = currentTier
					});
				int num = ((currentTier % 5 != 0) ? ((currentTier - 5) / 5 * 5 + 1) : (currentTier - 9));
				currentTier = num;
			}
			DifficultyLevelMeasurement lowDf = DifficultyLevelMeasurement.GetDifficultyLevelMeasurementByValue(90.0, 1);
			list.AddRange(source.Select((Recipe r) => new RecipeInfo
			{
				Recipe = r,
				IsQuestRelevant = false,
				ItemTierLevel = lowDf.GetCorrespondingItemTierLevel(r.ProductType)
			}));
		}
		return list.OrderByDescending((RecipeInfo r) => r.ItemTierLevel).ToList();
	}

