		attributeModifier.Value = num2;
		attributeModifier.Key = string.Empty;
		attributeModifier.AttributeModifierType = AttributeModifierType.Gear;
		return attributeModifier;
	}

protected AttributeModifier GeneratePrimaryAttribute(AttributeType type, int numberOfUpgrades)
	{
		double num = 0.0;
		double num2 = 0.0;
		if (type == AttributeType.Resilience || type == AttributeType.Allresistances || type == AttributeType.Vitality || type == AttributeType.Agility)
		{
			num = UnityEngine.Random.Range(0.1f, 0.2f);
			num2 = 0.01;
		}
		if (type == AttributeType.Strength || type == AttributeType.Intelligience)
		{
			num = UnityEngine.Random.Range(0.05f, 0.1f);
			num2 = 0.005;
		}
		if (type == AttributeType.CritDamage)
		{
			num = UnityEngine.Random.Range(0.2f, 0.4f);
			num2 = 0.02;
		}
		double num3 = num;
		for (int i = 0; i < numberOfUpgrades; i++)
		{
			num3 += num2 * (double)UnityEngine.Random.Range(0.8f, 1f);
		}
		AttributeModifier attributeModifier = new AttributeModifier();
		attributeModifier.AttributeType = type;
		attributeModifier.ModificationType = ((type != AttributeType.CritDamage) ? ModificationType.Multiplication : ModificationType.Addition);
		attributeModifier.Value = num3;
		attributeModifier.Key = string.Empty;
		attributeModifier.AttributeModifierType = AttributeModifierType.Gear;
		return attributeModifier;
	}

public TeamSetItemUpgradeResult Upgrade(Item item, int level)
	{
		TeamSetItemUpgradeResult teamSetItemUpgradeResult = new TeamSetItemUpgradeResult();
		teamSetItemUpgradeResult.BoostedAttributes = new List<AttributeModifier>();
		teamSetItemUpgradeResult.BoostedEffects = new List<ISpecialEffectDataLoad>();
		TeamSetItemUpgradeResult teamSetItemUpgradeResult2 = teamSetItemUpgradeResult;
		UnityEngine.Random.InitState(item.TeamSetSeed.GetValueOrDefault());
		Dictionary<AttributeType, int> attributeSeeds = new Dictionary<AttributeType, int>();
		Dictionary<SpecialEffectType, int> effectSeeds = new Dictionary<SpecialEffectType, int>();
		foreach (AttributeType potentialTeamUpgradeAttribute in item.PotentialTeamUpgradeAttributes)
		{
			attributeSeeds.Add(potentialTeamUpgradeAttribute, UnityEngine.Random.Range(1, 10000000));
		}
		foreach (SpecialEffectType potentialTeamPieceEffect in item.PotentialTeamPieceEffects)
		{
			effectSeeds.Add(potentialTeamPieceEffect, UnityEngine.Random.Range(1, 10000000));
		}
		int seed = UnityEngine.Random.Range(1, 10000000);
		int seed2 = UnityEngine.Random.Range(1, 10000000);
		int seed3 = UnityEngine.Random.Range(1, 10000000);
		AttributeType valueOrDefault = item.TeamSetPiecePrimaryAttributeType.GetValueOrDefault();
		if (level > 0)
		{
			int num = item.TeamSetUpgradeMarker.Length + 1;
			if (level != num && level != num - 1)
			{
				level = 1;
			}
		}
		item.TeamSetUpgradeMarker = string.Empty;
		for (int i = 0; i < level; i++)
		{
			item.TeamSetUpgradeMarker += ".";
		}
		UnityEngine.Random.InitState(seed);
		AttributeModifier item2 = GeneratePrimaryAttribute(valueOrDefault, level);
		item.PrimaryAttributeModifiers = new List<AttributeModifier> { item2 };
		item.AdditionalAttributeModifiers = new List<AttributeModifier>();
		item.SpecialEffects = new List<ISpecialEffectDataLoad>();
		item.AddedSpecialEffects = new List<ISpecialEffectDataLoad>();
		item.Level = level;
		teamSetItemUpgradeResult2.BoostedAttributes.Add(item2);
		List<AttributeType> list = new List<AttributeType>();
		List<AttributeType> potentialTeamUpgradeAttributes = item.PotentialTeamUpgradeAttributes;
		UnityEngine.Random.InitState(seed2);
		bool flag = false;
		for (int j = 0; j < level; j++)
		{
			if ((double)UnityEngine.Random.value <= 0.5)
			{
				AttributeType item3 = potentialTeamUpgradeAttributes[UnityEngine.Random.Range(0, potentialTeamUpgradeAttributes.Count)];
				list.Add(item3);
				if (j == level - 1)
				{
					flag = true;
				}
			}
		}
		if (list.Any())
		{
			IEnumerable<IGrouping<AttributeType, AttributeType>> source = from a in list
				group a by a;
			item.AdditionalAttributeModifiers = source.Select((IGrouping<AttributeType, AttributeType> g) => GenerateExtraAttribute(g.Key, g.Count(), attributeSeeds[g.Key])).ToList();
			if (flag)
			{
				AttributeType finaleffectedAttribute = list.Last();
				AttributeModifier item4 = item.AdditionalAttributeModifiers.FirstOrDefault((AttributeModifier a) => a.AttributeType == finaleffectedAttribute);
				teamSetItemUpgradeResult2.BoostedAttributes.Add(item4);
			}
		}
		int num2 = level / 10;
		List<SpecialEffectType> additionalEffects = new List<SpecialEffectType>();
		List<SpecialEffectType> potentialTeamPieceEffects = item.PotentialTeamPieceEffects;
		UnityEngine.Random.InitState(seed3);
		for (int num3 = 0; num3 < num2; num3++)
		{
			additionalEffects.Add(potentialTeamPieceEffects[UnityEngine.Random.Range(0, potentialTeamPieceEffects.Count)]);
		}
		if (additionalEffects.Any())
		{
			IEnumerable<IGrouping<SpecialEffectType, SpecialEffectType>> source2 = from e in additionalEffects
				group e by e;
			item.SpecialEffects = source2.Select((IGrouping<SpecialEffectType, SpecialEffectType> g) => GenerateEffect(g.Key, g.Count(), effectSeeds[g.Key])).ToList();
			if (level % 10 == 0)
			{
				ISpecialEffectDataLoad item5 = item.SpecialEffects.FirstOrDefault((ISpecialEffectDataLoad ef) => ef.GetSpecialEffectType() == additionalEffects.Last());
				teamSetItemUpgradeResult2.BoostedEffects.Add(item5);
			}
		}
		foreach (ISpecialEffectDataLoad specialEffect in item.SpecialEffects)
		{
			GameWorld.instance.PlayerProfile.UnlockEffect(specialEffect.GetSpecialEffectType());
		}
		return teamSetItemUpgradeResult2;
	}

